import React, { useEffect } from 'react';
import { StatusBar } from 'expo-status-bar';
import { NavigationContainer } from '@react-navigation/native';
import { createBottomTabNavigator } from '@react-navigation/bottom-tabs';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { SafeAreaProvider } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';

// Screens
import WriteScreen from './src/screens/WriteScreen';
import ChatScreen from './src/screens/ChatScreen';
import ReflectScreen from './src/screens/ReflectScreen';
import SettingsScreen from './src/screens/SettingsScreen';
import AuthScreen from './src/screens/AuthScreen';
import DonationScreen from './src/screens/DonationScreen';

// Stores
import { useAppStore } from './src/store/appStore';

// Styles
import './src/styles/global.css';

const Tab = createBottomTabNavigator();
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 5 * 60 * 1000, // 5 minutes
      retry: 1,
    },
  },
});

function MainTabs() {
  return (
    <Tab.Navigator
      screenOptions={({ route }) => ({
        tabBarIcon: ({ focused, color, size }) => {
          let iconName: keyof typeof Ionicons.glyphMap;

          if (route.name === 'Write') {
            iconName = focused ? 'create' : 'create-outline';
          } else if (route.name === 'Chat') {
            iconName = focused ? 'chatbubbles' : 'chatbubbles-outline';
          } else if (route.name === 'Reflect') {
            iconName = focused ? 'analytics' : 'analytics-outline';
          } else if (route.name === 'Support') {
            iconName = focused ? 'heart' : 'heart-outline';
          } else if (route.name === 'Settings') {
            iconName = focused ? 'settings' : 'settings-outline';
          } else {
            iconName = 'help-outline';
          }

          return <Ionicons name={iconName} size={size} color={color} />;
        },
        tabBarActiveTintColor: '#0ea5e9',
        tabBarInactiveTintColor: '#6b7280',
        tabBarStyle: {
          backgroundColor: '#ffffff',
          borderTopColor: '#e5e7eb',
          paddingBottom: 5,
          paddingTop: 5,
          height: 60,
        },
        headerStyle: {
          backgroundColor: '#ffffff',
          borderBottomColor: '#e5e7eb',
        },
        headerTintColor: '#1f2937',
        headerTitleStyle: {
          fontWeight: '600',
        },
      })}
    >
      <Tab.Screen 
        name="Write" 
        component={WriteScreen}
        options={{ title: 'Write' }}
      />
      <Tab.Screen 
        name="Chat" 
        component={ChatScreen}
        options={{ title: 'Chat' }}
      />
      <Tab.Screen 
        name="Reflect" 
        component={ReflectScreen}
        options={{ title: 'Reflect' }}
      />
      <Tab.Screen 
        name="Support" 
        component={DonationScreen}
        options={{ title: 'Support' }}
      />
      <Tab.Screen 
        name="Settings" 
        component={SettingsScreen}
        options={{ title: 'Settings' }}
      />
    </Tab.Navigator>
  );
}

export default function App() {
  const { isAuthenticated, isLoading, checkAuth } = useAppStore();

  useEffect(() => {
    if (!DEMO_MODE) {
      checkAuth();
    }
  }, []);

  if (isLoading && !DEMO_MODE) {
    return (
      <SafeAreaProvider>
        <QueryClientProvider client={queryClient}>
          <div className="flex-1 bg-white justify-center items-center">
            <div className="text-gray-600">Loading...</div>
          </div>
        </QueryClientProvider>
      </SafeAreaProvider>
    );
  }

  return (
    <SafeAreaProvider>
      <QueryClientProvider client={queryClient}>
        <NavigationContainer>
          <StatusBar style="auto" />
          {DEMO_MODE || isAuthenticated ? <MainTabs /> : <AuthScreen />}
        </NavigationContainer>
      </QueryClientProvider>
    </SafeAreaProvider>
  );
}
